      .replace(/~~(?<text>\S.*\S)~~/g, '$1')
      .replace(/!\[(?<alt>.*?)\][[(].*?[\])]/g, '$1')
      .replace(/\[\^.+?\](?:: .*$)?/g, '')
      .replace(/\[(?<alt>.*?)\][[(].*?[\])]/g, '$1')
      .replace(/`(?<text>.+?)`/g, '$1')
      .replace(/^\s{0,3}>\s?/g, '')
      .replace(/:::.*/, '')
      .replace(/\s?:(?:::|[^:\n])+:/g, '')
      .replace(/\{#*[\w-]+\}/, '')
      .trim();

    if (cleanedLine) {
